\title{The Exact Value of the Binomial GCD A080170:\\
A Disproof of Stephan's Conjecture and a Carry-Minimum Correction}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For an integer $k \ge 2$ define the \emph{binomial gcd}
\[
D(k) \;=\; \gcd_{2 \le q \le k+1} \bin{qk}{k},
\]
the integer sequence catalogued as OEIS \textbf{A080170}. Let
$P(n) = \max_{p \mid n} p^{\val_p(n)}$ denote the \emph{dominant prime power}
of $n$, where $\val_p$ is the $p$-adic valuation. Ralf Stephan's conjecture
(entry 17 in his list of conjectures on integer sequences) proposes an exact
closed form: $D(k) = P(k+1)$ whenever $\frac{k+1}{P(k+1)} \le P(k+1)$, and
$D(k) = 1$ otherwise.

We prove that the \textbf{exact-value} part of this conjecture is
\textbf{false}. The first counterexample is $k = 11$: with $n = 12 = 2^2\cdot 3$
the formula predicts $P(12) = 4$, but in fact $D(11) = 2$. The disproof is
structural rather than computational: the gcd divides the term $\bin{55}{11}$,
and a single base-$2$ carry shows $4 \nmid \bin{55}{11}$. Conversely, we prove
the conjecture is \textbf{exact on the prime fibre}: for every prime $p$ we have
$p \mid D(p-1)$ and $p^2 \nmid D(p-1)$, so the exact power of $p$ dividing
$D(p-1)$ is $p^1$. Both directions follow from \textbf{Kummer's theorem}, which
identifies $\val_p(\bin{qk}{k})$ with the number of base-$p$ carries when adding
$k$ and $(q-1)k$. We further record three conjectures that survived exhaustive
testing for $2 \le k \le 201$ and discuss their proof strategies.
\end{abstract}

\section{Introduction}

Divisibility properties of binomial coefficients form one of the oldest and most
productive corners of number theory. Classical results---Kummer's carry theorem
(1852), Lucas' congruence, and the gcd identities of a Pascal row---repeatedly
show that the arithmetic of $\bin{a}{b}$ is governed by digit-level
combinatorics in a prime base.

The sequence A080170 packages a particularly attractive instance:
\[
D(k) = \gcd_{2 \le q \le k+1} \bin{qk}{k}, \qquad k \ge 2.
\]
The first values are
\[
D(2),D(3),\dots = 3,\,4,\,5,\,3,\,7,\,8,\,9,\,5,\,11,\,2,\,13,\,7,\,5,\,16,\,17,\,9,\,19,\dots
\]
Numerically these track the dominant prime power of $k+1$ at the start, which led
Ralf Stephan to conjecture an exact closed form. This paper settles the
exact-value claim (false), proves the part that is true (the prime fibre), and
extracts the correct governing law from the failure.

Our contributions are: (1) a formally verified disproof of the exact-value
conjecture, first counterexample $k = 11$, via divisibility rather than
enumeration (Theorem~\ref{thm:disproof}); (2) formally verified exactness on the
prime fibre, $p \mid D(p-1)$ and $p^2 \nmid D(p-1)$ for every prime $p$
(Theorems~\ref{thm:pdvd} and \ref{thm:psq}); (3) a Kummer-based diagnosis of why
the conjecture fails in general but succeeds on prime powers, with a corrected
carry-minimum formula (Section~\ref{sec:corrected}).

\section{Definitions and preliminaries}

Throughout, $p$ is prime, $\val_p(n)$ is the $p$-adic valuation, and we write
$p^a \,\|\, n$ for $a = \val_p(n)$.

\begin{definition}[Binomial gcd, A080170]
For $k \ge 2$, $\displaystyle D(k) = \gcd_{2 \le q \le k+1} \bin{qk}{k}$.
\end{definition}

\begin{definition}[Dominant prime power]
For $n \ge 1$, $\displaystyle P(n) = \max_{p \mid n} p^{\val_p(n)}$, the largest
exact prime-power component of $n$. E.g. $P(12) = \max(2^2,3^1) = 4$ and
$P(360) = \max(2^3,3^2,5^1) = 9$.
\end{definition}

\begin{conjecture}[Stephan, entry 17]
For all $k \ge 2$, with $n = k+1$: if $n/P(n) \le P(n)$ then $D(k) = P(n)$, else
$D(k) = 1$. Equivalently $D(k) > 1 \iff n/P(n) \le P(n)$.
\end{conjecture}

\begin{lemma}[gcd divides each term]\label{lem:gcddvd}
For every $q$ with $2 \le q \le k+1$, $D(k) \mid \bin{qk}{k}$.
\end{lemma}
\begin{proof}
Immediate from the definition of gcd over a finite family.
\end{proof}

